    def distanceK(self, root, target, k):
        parent = {}
        def dfs(node, par):
            if node:
                parent[node] = par
                dfs(node.left, node)
                dfs(node.right, node)
        dfs(root, None)
        queue = [target]
        visited = {target}
        for _ in range(k):
            next_queue = []
            for node in queue:
                for nei in (node.left, node.right, parent[node]):
                    if nei and nei not in visited:
                        visited.add(nei)
                        next_queue.append(nei)
            queue = next_queue
